CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Categorias" (
    "CategoriaId" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    "CategoriaPadreId" integer,
    "Activo" boolean NOT NULL,
    CONSTRAINT "PK_Categorias" PRIMARY KEY ("CategoriaId"),
    CONSTRAINT "FK_Categorias_Categorias_CategoriaPadreId" FOREIGN KEY ("CategoriaPadreId") REFERENCES "Categorias" ("CategoriaId") ON DELETE RESTRICT
);

CREATE TABLE "CortesCaja" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FechaCorte" timestamp with time zone NOT NULL,
    "FondoInicial" numeric(18,2) NOT NULL,
    "TotalEfectivoSistema" numeric(18,2) NOT NULL,
    "EfectivoContado" numeric(18,2) NOT NULL,
    "Diferencia" numeric(18,2) NOT NULL,
    "TotalTarjeta" numeric(18,2) NOT NULL,
    "TotalTransferencia" numeric(18,2) NOT NULL,
    "GranTotal" numeric(18,2) NOT NULL,
    "TotalVentas" integer NOT NULL,
    "Observaciones" character varying(250) NOT NULL,
    CONSTRAINT "PK_CortesCaja" PRIMARY KEY ("Id")
);

CREATE TABLE "DireccionesEnvio" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UsuarioId" integer NOT NULL,
    "Calle" character varying(150) NOT NULL,
    "NumeroExterior" character varying(20) NOT NULL,
    "NumeroInterior" character varying(20),
    "Colonia" character varying(100) NOT NULL,
    "Ciudad" character varying(100) NOT NULL,
    "Estado" character varying(50) NOT NULL,
    "CodigoPostal" character varying(10) NOT NULL,
    "TelefonoContacto" character varying(20) NOT NULL,
    CONSTRAINT "PK_DireccionesEnvio" PRIMARY KEY ("Id")
);

CREATE TABLE "Marcas" (
    "MarcaId" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    "Activo" boolean NOT NULL,
    CONSTRAINT "PK_Marcas" PRIMARY KEY ("MarcaId")
);

CREATE TABLE "Ordenes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UsuarioId" integer NOT NULL,
    "DireccionEnvioId" integer NOT NULL,
    "FechaOrden" timestamp with time zone NOT NULL,
    "Subtotal" numeric(18,2) NOT NULL,
    "Iva" numeric(18,2) NOT NULL,
    "CostoFlete" numeric(18,2) NOT NULL,
    "Total" numeric(18,2) NOT NULL,
    "EstadoOrden" character varying(50) NOT NULL,
    "MetodoPago" character varying(50) NOT NULL,
    "PayPalOrderId" character varying(100),
    "ReferenciaPago" character varying(50),
    "Paqueteria" character varying(100),
    "NumeroGuia" character varying(100),
    "InventarioReservado" boolean NOT NULL,
    "InventarioReservaExpiraUtc" timestamp with time zone,
    CONSTRAINT "PK_Ordenes" PRIMARY KEY ("Id")
);

CREATE TABLE "OrdenesDetalles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "OrdenId" integer NOT NULL,
    "ProductoId" integer NOT NULL,
    "Cantidad" integer NOT NULL,
    "PrecioUnitario" numeric(18,2) NOT NULL,
    "EsBajoPedido" boolean NOT NULL,
    CONSTRAINT "PK_OrdenesDetalles" PRIMARY KEY ("Id")
);

CREATE TABLE "Pedidos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Fecha" timestamp with time zone NOT NULL,
    "Total" numeric(18,2) NOT NULL,
    "UsuarioId" integer NOT NULL,
    CONSTRAINT "PK_Pedidos" PRIMARY KEY ("Id")
);

CREATE TABLE "SolicitudesFacturacion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UsuarioId" integer,
    "NumeroOrdenOid" character varying(50) NOT NULL,
    "FechaTicket" character varying(50) NOT NULL,
    "Importe" numeric(18,2) NOT NULL,
    "Rfc" character varying(20) NOT NULL,
    "RazonSocial" character varying(250) NOT NULL,
    "CodigoPostalFiscal" character varying(10) NOT NULL,
    "RegimenFiscal" character varying(100) NOT NULL,
    "FormaPago" character varying(50) NOT NULL,
    "UsoCfdi" character varying(50) NOT NULL,
    "Correo" character varying(150) NOT NULL,
    "Celular" character varying(20) NOT NULL,
    "Observaciones" text,
    "Estatus" character varying(50) NOT NULL,
    "FechaSolicitud" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_SolicitudesFacturacion" PRIMARY KEY ("Id")
);

CREATE TABLE "Usuarios" (
    "UsuarioId" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    "ApellidoPaterno" text NOT NULL,
    "ApellidoMaterno" text NOT NULL,
    "FechaNacimiento" date NOT NULL,
    "Direccion" text NOT NULL,
    "Email" text NOT NULL,
    "PasswordHash" text NOT NULL,
    "Rol" text NOT NULL,
    "FechaRegistro" timestamp with time zone NOT NULL,
    "Telefono" text NOT NULL,
    "CodigoPostal" text NOT NULL,
    "Colonia" text NOT NULL,
    "Activo" boolean NOT NULL,
    "CanalVerificacionPreferido" text,
    "CodigoVerificacion" text,
    "CodigoVerificacionExpira" timestamp with time zone,
    "TokenRecuperacion" text,
    "TokenRecuperacionExpira" timestamp with time zone,
    CONSTRAINT "PK_Usuarios" PRIMARY KEY ("UsuarioId")
);

CREATE TABLE "ZonasEnvio" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Estado" character varying(50) NOT NULL,
    "CostoFlete" numeric(18,2) NOT NULL,
    "DiasEntregaEstimados" integer NOT NULL,
    CONSTRAINT "PK_ZonasEnvio" PRIMARY KEY ("Id")
);

CREATE TABLE "SubCategorias" (
    "SubCategoriaId" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    "CategoriaId" integer NOT NULL,
    CONSTRAINT "PK_SubCategorias" PRIMARY KEY ("SubCategoriaId"),
    CONSTRAINT "FK_SubCategorias_Categorias_CategoriaId" FOREIGN KEY ("CategoriaId") REFERENCES "Categorias" ("CategoriaId") ON DELETE CASCADE
);

CREATE TABLE "VentasFisicas" (
    "VentaId" integer GENERATED BY DEFAULT AS IDENTITY,
    "FechaCreacion" timestamp with time zone NOT NULL,
    "Total" numeric(18,2) NOT NULL,
    "MetodoPago" character varying(50) NOT NULL,
    "Cliente" character varying(100) NOT NULL,
    "CorteId" integer,
    "CorteCajaId" integer,
    CONSTRAINT "PK_VentasFisicas" PRIMARY KEY ("VentaId"),
    CONSTRAINT "FK_VentasFisicas_CortesCaja_CorteCajaId" FOREIGN KEY ("CorteCajaId") REFERENCES "CortesCaja" ("Id")
);

CREATE TABLE "DetallePedidos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PedidoId" integer NOT NULL,
    "ProductoId" integer NOT NULL,
    "Cantidad" integer NOT NULL,
    "PrecioUnitario" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_DetallePedidos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DetallePedidos_Pedidos_PedidoId" FOREIGN KEY ("PedidoId") REFERENCES "Pedidos" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Productos" (
    "ProductoId" integer GENERATED BY DEFAULT AS IDENTITY,
    "SKU" text NOT NULL,
    "Nombre" text NOT NULL,
    "Descripcion" text,
    "PrecioPublico" numeric(18,2) NOT NULL,
    "DescuentoPorcentaje" numeric(5,2) NOT NULL,
    "OfertaInicioUtc" timestamp with time zone,
    "OfertaFinUtc" timestamp with time zone,
    "EsDestacado" boolean NOT NULL,
    "DestacadoInicioUtc" timestamp with time zone,
    "DestacadoFinUtc" timestamp with time zone,
    "Stock" integer NOT NULL,
    "PermiteBajoPedido" boolean NOT NULL,
    "EsServicio" boolean NOT NULL,
    "FechaCreacion" timestamp with time zone NOT NULL,
    "ImagenUrl" text,
    "CategoriaId" integer NOT NULL,
    "MainMarcadId" integer NOT NULL,
    "SubCategoriaId" integer,
    CONSTRAINT "PK_Productos" PRIMARY KEY ("ProductoId"),
    CONSTRAINT "FK_Productos_Categorias_CategoriaId" FOREIGN KEY ("CategoriaId") REFERENCES "Categorias" ("CategoriaId") ON DELETE CASCADE,
    CONSTRAINT "FK_Productos_Marcas_MainMarcadId" FOREIGN KEY ("MainMarcadId") REFERENCES "Marcas" ("MarcaId") ON DELETE CASCADE,
    CONSTRAINT "FK_Productos_SubCategorias_SubCategoriaId" FOREIGN KEY ("SubCategoriaId") REFERENCES "SubCategorias" ("SubCategoriaId") ON DELETE RESTRICT
);

CREATE TABLE "VentasFisicasDetalles" (
    "DetalleVentaId" integer GENERATED BY DEFAULT AS IDENTITY,
    "VentaId" integer NOT NULL,
    "ProductoId" integer NOT NULL,
    "Cantidad" integer NOT NULL,
    "PrecioUnitario" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_VentasFisicasDetalles" PRIMARY KEY ("DetalleVentaId"),
    CONSTRAINT "FK_VentasFisicasDetalles_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("ProductoId") ON DELETE CASCADE,
    CONSTRAINT "FK_VentasFisicasDetalles_VentasFisicas_VentaId" FOREIGN KEY ("VentaId") REFERENCES "VentasFisicas" ("VentaId") ON DELETE CASCADE
);

